#!/usr/bin/env python
"""Django management entry point for erp-portal."""
import os
import sys


def main():
    os.environ.setdefault("DJANGO_SETTINGS_MODULE", "sampleproj.settings")
    from django.core.management import execute_from_command_line

    execute_from_command_line(sys.argv)


if __name__ == "__main__":
    main()

"""Pricing rules for subscription plans. Kept server-side on purpose."""
from dataclasses import dataclass
from decimal import Decimal, ROUND_HALF_UP


@dataclass(frozen=True)
class Plan:
    code: str
    monthly_price: Decimal
    seats_included: int


PLANS = {
    "starter": Plan("starter", Decimal("99.00"), 3),
    "growth": Plan("growth", Decimal("299.00"), 10),
    "enterprise": Plan("enterprise", Decimal("899.00"), 50),
}
ENTERPRISE_DISCOUNT = Decimal("0.82")
OVERAGE_PRICE = Decimal("19.00")


def _money(value: Decimal) -> str:
    return str(value.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


def calculate_price(customer, plan_code: str, seats: int = 0) -> Decimal:
    plan = PLANS[plan_code]
    base = plan.monthly_price
    extra_seats = max(0, seats - plan.seats_included)
    total = base + OVERAGE_PRICE * extra_seats
    if customer.is_enterprise:
        total *= ENTERPRISE_DISCOUNT
    return total.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)


def quote_for_customer(customer_code: str, plan_code: str) -> dict:
    plan = PLANS[plan_code]
    return {
        "plan": plan.code,
        "monthly_price": _money(plan.monthly_price),
        "currency": "CNY",
        "seats_included": plan.seats_included,
        "quoted_for": customer_code,
    }

from django.http import JsonResponse
from django.views.decorators.http import require_GET

from .services.pricing import quote_for_customer


@require_GET
def quote(request):
    customer = request.GET.get("customer", "standard")
    plan = request.GET.get("plan", "growth")
    return JsonResponse(quote_for_customer(customer, plan))
